    <script type="module">
        import {
            onCLS,
            onFCP,
            onFID,
            onINP,
            onLCP,
            onTTFB
        } from 'https://unpkg.com/web-vitals@3.5.2/dist/web-vitals.js?module';

        const queue = new Map();
        let shouldLogQueuedMetrics = true;

        const pageInfo = {
            handle: pageData.id,
            url: window.location.href,
        };

        function isMetricValid(metric) {
            return metric && typeof metric.value === 'number' && !isNaN(metric.value) && metric.value >= 0;
        }

        function queueMetric(metric) {
            if (!isMetricValid(metric) || queue.has(metric.name)) return;
            queue.set(metric.name, metric);
        }

        function logQueuedMetrics() {
            if (queue.size === 0 || !shouldLogQueuedMetrics) return;

            shouldLogQueuedMetrics = false;
            logMetrics([...queue.values()]);
        }

        function logMetrics(metrics) {
            if (metrics.length === 0) return;

            const webVitals = Object.fromEntries(
                metrics.map(({
                    name,
                    rating,
                    value
                }) => [name, {
                    rating,
                    value
                }])
            );

            const data = JSON.stringify({
                pageInfo,
                webVitals
            });

            if (!navigator.sendBeacon) {
                fetch('/stats/web_vitals/', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: data
                }).catch(console.error);
            } else {
                navigator.sendBeacon('/stats/web_vitals/', data);
            }
        }


        /**
         * Log network metrics like TTFB, DNS lookup, and connection negotiation
         */
        function logNetworkMetrics(ttfb) {
            if (!isMetricValid(ttfb)) return;

            const metrics = [ttfb];

            const pageNav = ttfb.entries?.[0];
            if (pageNav) {
                const dnsLookup = {
                    name: 'DNS_LOOKUP',
                    value: pageNav.domainLookupEnd - pageNav.domainLookupStart
                };
                const connectionNegotiation = {
                    name: 'CONNECTION_NEGOTIATION',
                    value: pageNav.connectEnd - pageNav.connectStart
                };

                if (isMetricValid(dnsLookup)) metrics.push(dnsLookup);
                if (isMetricValid(connectionNegotiation)) metrics.push(connectionNegotiation);
            }

            logMetrics(metrics);
        }

        function listenWebMetrics() {
            onCLS(queueMetric);
            onFCP(queueMetric);
            onFID(queueMetric);
            onINP(queueMetric);
            onLCP(queueMetric);
            onTTFB(logNetworkMetrics);

            addEventListener('visibilitychange', () => {
                if (document.visibilityState === 'hidden') logQueuedMetrics();
            }, {
                once: true
            });

            addEventListener('beforeunload', logQueuedMetrics);

            // Safari does not reliably fire the `visibilitychange` event when the page is being unloaded.
            addEventListener('pagehide', logQueuedMetrics);
        }

        listenWebMetrics();
    </script>

