    /* Hamburger Modal - Vanilla JS fallback styles */
    #nav-hamburger {
        position: fixed;
        top: 0;
        left: 0;
        width: 85%;
        max-width: 320px;
        height: 100%;
        background: #fff;
        z-index: 2000;
        transform: translateX(-100%);
        transition: transform 0.3s ease;
        overflow-y: auto;
    }
    #nav-hamburger.modal-show {
        transform: translateX(0);
    }
    .js-modal-overlay[data-modal-id="#nav-hamburger"] {
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: rgba(0,0,0,0.5);
        z-index: 1999;
    }
    /* Hamburger submenu panel */
    #nav-hamburger .js-menu-panel {
        position: fixed;
        top: 0;
        left: 0;
        width: 85%;
        max-width: 320px;
        height: 100%;
        background: #fff;
        z-index: 2001;
        transform: translateX(-100%);
        transition: transform 0.3s ease;
        overflow-y: auto;
    }
    #nav-hamburger .js-menu-panel.nav-list-panel-show {
        transform: translateX(0);
    }
