    <script type="text/javascript">
        LS.ready.then(function() {











            // Move to our_content
            window.urls = {
                "shippingUrl": "\/envio\/"
            }


            document.addEventListener('lazybeforeunveil', function(e) {
                if ((e.target.parentElement) && (e.target.nextElementSibling)) {
                    var parent = e.target.parentElement;
                    var sibling = e.target.nextElementSibling;
                    if (sibling.classList.contains('js-lazy-loading-preloader')) {
                        sibling.style.display = 'none';
                        parent.style.display = 'block';
                    }
                }
            });


            window.lazySizesConfig = window.lazySizesConfig || {};
            lazySizesConfig.hFac = 0.4;


            DOMContentLoaded.addEventOrExecute(() => {



                jQueryNuvem(".js-notification-close, .js-tooltip-close").on("click", function(e) {
                    e.preventDefault();
                    jQueryNuvem(e.currentTarget).closest(".js-notification, .js-tooltip").hide();
                });


                jQueryNuvem(document).on("click", ".js-tooltip-open", function(e) {
                    e.preventDefault();
                    jQueryNuvem(this).next(".js-tooltip").show();
                });



                var $notification_status_page = jQueryNuvem(".js-notification-status-page");
                var $fixed_bottom_button = jQueryNuvem(".js-btn-fixed-bottom");
                var head_height = jQueryNuvem(".js-head-main").height();


                if ($notification_status_page.length > 0) {
                    if (LS.shouldShowOrderStatusNotification($notification_status_page.data('url'))) {

                        $notification_status_page.css("top", head_height + 15 + "px");
                        $notification_status_page.show();
                    };
                    jQueryNuvem(".js-notification-status-page-close").on("click", function(e) {
                        e.preventDefault();
                        LS.dontShowOrderStatusNotificationAgain($notification_status_page.data(
                            'url'));
                    });
                }


                jQueryNuvem(".js-cart-notification-close").on("click", function() {
                    jQueryNuvem(".js-alert-added-to-cart").removeClass("notification-visible")
                        .addClass("notification-hidden");
                    setTimeout(function() {
                        jQueryNuvem('.js-cart-notification-item-img').attr('src', '');
                        jQueryNuvem(".js-alert-added-to-cart").hide();
                    }, 2000);
                });





                const footerLegal = jQueryNuvem(".js-footer-legal");

                restoreNotifications = function() {

                    // Whatsapp button position
                    $fixed_bottom_button.css("marginBottom", "0");


                    footerLegal.removeAttr("style");

                };

                if (!window.cookieNotificationService.isAcknowledged()) {
                    jQueryNuvem(".js-notification-cookie-banner").show();

                    const cookieBannerHeight = jQueryNuvem(".js-notification-cookie-banner").outerHeight();


                    footerLegal.css("paddingBottom", cookieBannerHeight + 40 + "px");

                    if (window.innerWidth < 768) {


                        $fixed_bottom_button.css("marginBottom", cookieBannerHeight + 20 + "px");
                    }

                }

                jQueryNuvem(".js-acknowledge-cookies").on("click", function(e) {
                    window.cookieNotificationService.acknowledge();

                    footerLegal.removeAttr("style");
                    restoreNotifications();
                });





                resetSearchBox = function() {


                    jQueryNuvem(".js-search-input").val("");
                    jQueryNuvem(".js-search-form-suggestions").hide();

                    const empty_search = jQueryNuvem(".js-empty-search");
                    const empty_submit = jQueryNuvem(".js-search-input-submit");

                    empty_search.fadeOut(100);
                    empty_submit.fadeIn(100);

                };


                if (window.innerWidth < 768) {


                    cleanURLHash = function() {
                        const uri = window.location.toString();
                        const clean_uri = uri.substring(0, uri.indexOf("#"));
                        window.history.replaceState({}, document.title, clean_uri);
                    };


                    goBackBrowser = function() {
                        cleanURLHash();
                        history.back();
                    };


                    if (window.location.href.indexOf("modal-fullscreen") > -1) {
                        cleanURLHash();
                    }


                    jQueryNuvem(document).on("click", ".js-fullscreen-modal-open", function(e) {
                        e.preventDefault();
                        var modal_url_hash = jQueryNuvem(this).data("modalUrl");
                        window.location.hash = modal_url_hash;
                    });


                    jQueryNuvem(document).on("click", ".js-fullscreen-modal-close", function(e) {
                        e.preventDefault();
                        goBackBrowser();
                    });


                    window.onhashchange = function() {
                        if (window.location.href.indexOf("modal-fullscreen") <= -1) {


                            if (jQueryNuvem(".js-fullscreen-modal").hasClass("modal-show")) {


                                if (jQueryNuvem(".js-modal.modal-show").length == 1) {
                                    jQueryNuvem("body").removeClass("overflow-none");
                                }
                                var $opened_modal = jQueryNuvem(".js-fullscreen-modal.modal-show");
                                var $opened_modal_overlay = $opened_modal.prev();

                                $opened_modal.removeClass("modal-show");
                                setTimeout(() => $opened_modal.hide(), 500);
                                $opened_modal_overlay.fadeOut(500);


                                resetSearchBox();


                            }
                        }
                    }

                }

                modalOpen = function(modal_id, openType) {

                    var $overlay_id = jQueryNuvem('.js-modal-overlay[data-modal-id="' + modal_id +
                        '"]');

                    if (jQueryNuvem(modal_id).hasClass("modal-show")) {
                        if (jQueryNuvem(".js-modal.modal-show").length == 1) {
                            jQueryNuvem("body").removeClass("overflow-none");
                        }
                        let modal = jQueryNuvem(modal_id).removeClass("modal-show");
                        setTimeout(() => modal.hide(), 500);
                    } else {


                        if (!jQueryNuvem(".js-modal.modal-show").length) {
                            jQueryNuvem("body").addClass("overflow-none move-right");
                        }

                        jQueryNuvem(modal_id).detach().appendTo("body");
                        jQueryNuvem(modal_id).show().addClass("modal-show");

                        if (((jQueryNuvem(modal_id).hasClass("js-modal-overlay-md")) && (window
                                .innerWidth > 768)) || (!jQueryNuvem(modal_id).hasClass(
                                "js-modal-overlay-md"))) {
                            $overlay_id.fadeIn(400);
                            $overlay_id.detach().insertBefore(modal_id);
                        }
                    }


                    if (openType == 'openFullScreenWithoutClick' && window.innerWidth < 768 &&
                        jQueryNuvem(modal_id).hasClass("js-fullscreen-modal")) {
                        var modal_url_hash = jQueryNuvem(modal_id).data("modalUrl");
                        window.location.hash = modal_url_hash;
                    }

                };

                jQueryNuvem(document).on("click", ".js-modal-open", function(e) {
                    e.preventDefault();
                    const modal_id = jQueryNuvem(this).data('toggle');
                    modalOpen(modal_id);
                });

                jQueryNuvem(document).on("click", ".js-modal-close", function(e) {
                    e.preventDefault();


                    if (jQueryNuvem(".js-modal.modal-show").length == 1) {
                        jQueryNuvem("body").removeClass("overflow-none");
                    }
                    var $modal = jQueryNuvem(this).closest(".js-modal");
                    var modal_id = $modal.attr('id');
                    var $overlay_id = jQueryNuvem('.js-modal-overlay[data-modal-id="#' + modal_id +
                        '"]');
                    $modal.removeClass("modal-show");
                    setTimeout(() => $modal.hide(), 500);
                    $overlay_id.fadeOut(500);


                    if ((window.innerWidth < 768) && (jQueryNuvem(this).hasClass(
                            ".js-fullscreen-modal-close"))) {
                        goBackBrowser();
                    }


                    resetSearchBox();


                });

                jQueryNuvem(document).on("click", ".js-modal-overlay", function(e) {
                    e.preventDefault();


                    if (jQueryNuvem(".js-modal.modal-show").length == 1) {
                        jQueryNuvem("body").removeClass("overflow-none");
                    }

                    var modal_id = jQueryNuvem(this).data('modalId');
                    let modal = jQueryNuvem(modal_id).removeClass("modal-show");
                    setTimeout(() => modal.hide(), 500);
                    jQueryNuvem(this).fadeOut(500);


                    resetSearchBox();


                });


                jQueryNuvem(document).on("click", ".js-card-collapse-toggle", function(e) {
                    e.preventDefault();
                    var parent = jQueryNuvem(this).closest(".js-card-collapse");
                    parent.find(".js-card-collapse-icon").toggle();
                    parent.toggleClass('active');
                });


                const inViewport = (entries, observer) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting && !entry.target.observed) {
                            entry.target.classList.add("is-inViewport");
                            entry.target.observed = true;
                        }
                    });
                };

                // Attach observer to every [data-transition] element:
                const ELs_inViewport = document.querySelectorAll('[data-transition]');
                ELs_inViewport.forEach(EL => {
                    EL.observed = false; // Initialize the observed flag for each element
                    const Obs = new IntersectionObserver(inViewport);
                    Obs.observe(EL);
                });

                applyMarqueeAnimation = function(marqueeSelector, textSelector) {


                    var defaultDelay = 5;
                    var defaultWidth = 300;

                    var animatedWidth = jQueryNuvem(textSelector).first(el => el.offsetWidth);
                    var newDelay = defaultDelay * (animatedWidth / defaultWidth) * 1.5;

                    if ((window.innerWidth > 768) && (newDelay < 40)) {

                        var newDelay = newDelay + 20;
                    }

                    jQueryNuvem(marqueeSelector).css("animation", "marquee " + newDelay +
                        "s linear infinite");
                };



                applyMarqueeAnimation(".js-welcome-animated", ".js-welcome-text-container");









                var $category_controls = jQueryNuvem(".js-category-controls");



                jQueryNuvem(".js-toggle-menu-panel").click(function(e) {
                    e.preventDefault();
                    jQueryNuvem(this).next(".js-menu-panel").show().addClass("nav-list-panel-show");
                });

                jQueryNuvem(".js-toggle-menu-back").click(function(e) {
                    e.preventDefault();
                    var $panel_to_change = jQueryNuvem(this).closest(".js-menu-panel");
                    $panel_to_change.removeClass("nav-list-panel-show");
                    setTimeout(function() {
                        $panel_to_change.hide();
                    }, 600);
                });

                closeHamburgerSubpanels = function() {
                    jQueryNuvem("#nav-hamburger").addClass("modal-transition-fast");
                    jQueryNuvem(".js-menu-panel").removeClass("nav-list-panel-show");

                    setTimeout(function() {
                        jQueryNuvem(".js-menu-panel").hide();
                        jQueryNuvem("#nav-hamburger").removeClass("modal-transition-fast");
                    }, 1000);
                };

