                var nav_height = jQueryNuvem(".js-head-main").innerHeight();






                const noStockVariants = (container = null) => {

                    const config = {
                        variantsGroup: ".js-product-variants-group",
                        variantButton: ".js-insta-variant",
                        noStockClass: "btn-variant-no-stock",
                        dataVariationId: "data-variation-id",
                        dataOption: "data-option"
                    };

                    const wrapper = container ? container : jQueryNuvem('#single-product');
                    if (!wrapper) return;

                    const dataVariants = wrapper.data('variants');
                    const variantsLength = wrapper.find(config.variantsGroup).length;

                    const getOptions = (productVariationId, variantOption) => {
                        if (productVariationId === 2) {
                            return {
                                option0: String(wrapper.find(
                                    `${config.variantsGroup}[${config.dataVariationId}="0"] select`
                                ).val()),
                                option1: String(wrapper.find(
                                    `${config.variantsGroup}[${config.dataVariationId}="1"] select`
                                ).val()),
                                option2: String(jQueryNuvem(variantOption).attr('data-option')),
                            };
                        } else if (productVariationId === 1) {
                            return {
                                option0: String(wrapper.find(
                                    `${config.variantsGroup}[${config.dataVariationId}="0"] select`
                                ).val()),
                                option1: String(jQueryNuvem(variantOption).attr('data-option')),
                            };
                        } else {
                            return {
                                option0: String(jQueryNuvem(variantOption).attr('data-option')),
                            };
                        }
                    };

                    const filterVariants = (options) => {
                        return dataVariants.filter(variant => {
                            return Object.keys(options).every(optionKey => variant[
                                optionKey] === options[optionKey]) && variant.available;
                        });
                    };

                    const updateStockStatus = (productVariationId) => {
                        const variationGroup = wrapper.find(
                            `${config.variantsGroup}[${config.dataVariationId}="${productVariationId}"]`
                        );
                        variationGroup.find(`${config.variantButton}.${config.noStockClass}`)
                            .removeClass(config.noStockClass);

                        variationGroup.find(config.variantButton).each((variantOption, item) => {
                            const options = getOptions(productVariationId, variantOption);
                            const itemsAvailable = filterVariants(options);
                            const button = wrapper.find(
                                `${config.variantButton}[${config.dataOption}="${options[`option${productVariationId}`].replace(/"/g, '\\"')}"]`
                            );

                            if (!itemsAvailable.length) {
                                button.addClass(config.noStockClass);
                            }
                        });
                    };

                    for (let productVariationId = variantsLength - 1; productVariationId >=
                        0; productVariationId--) {
                        updateStockStatus(productVariationId);
                    }
                };

                noStockVariants();



                changeVariantButton = function(selector, parentSelector) {
                    selector.siblings().removeClass("selected");
                    selector.addClass("selected");
                    var option_id = selector.attr('data-option');
                    var parent = selector.closest(parentSelector);
                    var selected_option = parent.find('.js-variation-option option').filter(function(
                        el) {
                        return el.value == option_id;
                    });
                    selected_option.prop('selected', true).trigger('change');
                    parent.find('.js-insta-variation-label').html(option_id);
                }


                jQueryNuvem(document).on("click", ".js-insta-variant", function(e) {
                    e.preventDefault();
                    $this = jQueryNuvem(this);
                    changeVariantButton($this, '.js-product-variants-group');
                });




                if (window.innerWidth > 767) {
