                        e.preventDefault();
                        $this = jQueryNuvem(this);
                        changeVariantButton($this, '.js-item-product');
                    });
                }



                LS.registerOnChangeVariant(function(variant) {
                    const productContainer = jQueryNuvem('.js-item-product[data-product-id="' +
                        variant.product_id + '"]');
                    const current_image = productContainer.find('.js-item-image');
                    current_image.attr('srcset', variant.image_url);


                    productContainer.find(".js-product-item-private-with-secondary-images")
                        .addClass("product-item-secondary-images-disabled");
                });





                function get_max_installments_without_interests(number_of_installment, installment_data,
                    max_installments_without_interests) {
                    if (parseInt(number_of_installment) > parseInt(max_installments_without_interests[0])) {
                        if (installment_data.without_interests) {
                            return [number_of_installment, installment_data.installment_value.toFixed(2)];
                        }
                    }
                    return max_installments_without_interests;
                }


                function get_max_installments_with_interests(number_of_installment, installment_data,
                    max_installments_with_interests) {
                    if (parseInt(number_of_installment) > parseInt(max_installments_with_interests[0])) {
                        if (installment_data.without_interests == false) {
                            return [number_of_installment, installment_data.installment_value.toFixed(2)];
                        }
                    }
                    return max_installments_with_interests;
                }


                function refreshInstallmentv2(price) {
                    jQueryNuvem(".js-modal-installment-price").each(function(el) {
                        const installment = Number(jQueryNuvem(el).data('installment'));
                        jQueryNuvem(el).text(LS.currency.display_short + (price / installment)
                            .toLocaleString('de-DE', {
                                maximumFractionDigits: 2,
                                minimumFractionDigits: 2
                            }));
                    });
                }


                function refreshPaymentDiscount(price) {
                    jQueryNuvem(".js-price-with-discount").each(function(el) {
                        const payment_discount = jQueryNuvem(el).data('paymentDiscount');
                        jQueryNuvem(el).text(LS.formatToCurrency(price - ((price *
                            payment_discount) / 100)))
                    });
                }




                function changeVariant(variant) {
                    jQueryNuvem(".js-product-detail .js-shipping-calculator-response").hide();
                    jQueryNuvem("#shipping-variant-id").val(variant.id);

                    var parent = jQueryNuvem("body");
                    if (variant.element) {
                        parent = jQueryNuvem(variant.element);
                        if (parent.hasClass("js-quickshop-container")) {
                            var quick_id = parent.attr("data-quickshop-id");
                            var parent = jQueryNuvem('.js-quickshop-container[data-quickshop-id="' +
                                quick_id + '"]');
                        }
                    }

                    if (parent.hasClass("js-quickshop-container")) {
                        var itemContainer = parent.closest('.js-item-product');
                        if (itemContainer.hasClass("js-item-slide")) {
                            var parent = jQueryNuvem(
                                '.js-swiper-slide-visible .js-quickshop-container[data-quickshop-id="' +
                                quick_id + '"]');
                        }
                        noStockVariants(parent);
                    } else {
                        noStockVariants();
                    }

                    var sku = parent.find('.js-product-sku');
                    if (sku.length) {
                        sku.text(variant.sku).show();
                    }



                    var installment_helper = function($element, amount, price) {
                        $element.find('.js-installment-amount').text(amount);
                        $element.find('.js-installment-price').attr("data-value", price);
                        $element.find('.js-installment-price').text(LS.currency.display_short +
                            parseFloat(price).toLocaleString('de-DE', {
                                minimumFractionDigits: 2
                            }));
                        if (variant.price_short && Math.abs(variant.price_number - price * amount) <
                            1) {
                            $element.find('.js-installment-total-price').text((variant.price_short)
                                .toLocaleString('de-DE', {
                                    minimumFractionDigits: 2
                                }));
                        } else {
                            $element.find('.js-installment-total-price').text(LS.currency
                                .display_short + (price * amount).toLocaleString('de-DE', {
                                    minimumFractionDigits: 2
                                }));
                        }
                    };

                    if (variant.installments_data) {
                        var variant_installments = JSON.parse(variant.installments_data);
                        var max_installments_without_interests = [0, 0];
                        var max_installments_with_interests = [0, 0];

                        jQueryNuvem('.js-payment-provider-installments-row').hide();

                        for (let payment_method in variant_installments) {

                            var paymentMethodId = '#installment_' + payment_method.replace(" ", "_") + '_1';
                            var minimumInstallmentValue = jQueryNuvem(paymentMethodId).closest(
                                '.js-info-payment-method').attr("data-minimum-installment-value");

                            let installments = variant_installments[payment_method];
                            for (let number_of_installment in installments) {
                                let installment_data = installments[number_of_installment];
                                max_installments_without_interests = get_max_installments_without_interests(
                                    number_of_installment, installment_data,
                                    max_installments_without_interests);
                                max_installments_with_interests = get_max_installments_with_interests(
                                    number_of_installment, installment_data,
                                    max_installments_with_interests);
                                var installment_container_selector = '#installment_' + payment_method
                                    .replace(" ", "_") + '_' + number_of_installment;

                                if (minimumInstallmentValue <= installment_data.installment_value) {
                                    jQueryNuvem(installment_container_selector).show();
                                }

                                if (!parent.hasClass("js-quickshop-container")) {
                                    installment_helper(jQueryNuvem(installment_container_selector),
                                        number_of_installment, installment_data.installment_value
                                        .toFixed(2));
                                }
                            }
                        }
                        var $installments_container = jQueryNuvem(variant.element +
                            ' .js-max-installments-container .js-max-installments');
                        var $installments_modal_link = jQueryNuvem(variant.element + ' #btn-installments');
                        var $payments_module = jQueryNuvem(variant.element +
                            ' .js-product-payments-container');
                        var $installmens_card_icon = jQueryNuvem(variant.element +
                            ' .js-installments-credit-card-icon');

                        var installments_to_use = max_installments_without_interests[0] > 1 ?
                            max_installments_without_interests : max_installments_with_interests;

                        if (installments_to_use[0] <= 1) {
                            $installments_container.hide();
                            $installments_modal_link.hide();
                            $payments_module.hide();
                            $installmens_card_icon.hide();
                        } else {
                            $installments_container.show();
                            $installments_modal_link.show();
                            $payments_module.show();
                            $installmens_card_icon.show();
                            installment_helper($installments_container, installments_to_use[0],
                                installments_to_use[1]);
                        }
                    }

                    if (!parent.hasClass("js-quickshop-container")) {
                        jQueryNuvem('#installments-modal .js-installments-one-payment').text(variant
                            .price_short).attr("data-value", variant.price_number);
                    }

                    if (variant.price_short) {
                        parent.find('.js-price-display').text(variant.price_short).show();
                        parent.find('.js-price-display').attr("content", variant.price_number).data(
                            'productPrice', variant.price_number_raw);

                        parent.find('.js-payment-discount-price-product').text(variant
                            .price_with_payment_discount_short);
                        parent.find('.js-payment-discount-price-product-container').show();

                        parent.find('.js-price-without-taxes').text(variant.price_without_taxes);
                        parent.find('.js-price-without-taxes-container').show();
                    } else {
                        parent.find(
                            '.js-price-display, .js-payment-discount-price-product-container, .js-price-without-taxes-container'
                        ).hide();
                    }

                    if ((variant.compare_at_price_short) && !(parent.find(".js-price-display").css(
                            "display") == "none")) {
                        parent.find('.js-compare-price-display').text(variant.compare_at_price_short)
                            .show();
                    } else {
                        parent.find('.js-compare-price-display').hide();
                    }

                    var button = parent.find('.js-addtocart');
                    const quickshopButtonWording = parent.find('.js-open-quickshop-wording');
                    const quickshopButtonIcon = parent.find('.js-open-quickshop-icon');
                    button.removeClass('cart').removeClass('contact').removeClass('nostock');
                    var $product_shipping_calculator = parent.find("#product-shipping-container");


                    if (!variant.available) {
                        button.val('Sin stock');
                        button.addClass('nostock');
                        button.attr('disabled', 'disabled');
                        quickshopButtonWording.text('Sin stock');
                        quickshopButtonIcon.addClass("d-none").removeClass("d-md-inline");
                        $product_shipping_calculator.hide();
                    } else if (variant.contact) {
                        button.val('Consultar precio');
                        button.addClass('contact');
                        button.removeAttr('disabled');
                        quickshopButtonWording.text('Consultar precio');
                        quickshopButtonIcon.addClass("d-none").removeClass("d-md-inline");
                        $product_shipping_calculator.hide();
                    } else {
                        button.val('Agregar al carrito');
                        button.addClass('cart');
                        button.removeAttr('disabled');
                        quickshopButtonWording.text('Comprar');
                        quickshopButtonIcon.addClass("d-md-inline");
                        $product_shipping_calculator.show();
                    }



                    if (variant.stock == 1) {
                        parent.find('.js-last-product').show();
                    } else {
                        parent.find('.js-last-product').hide();
                    }



                    LS.updateShippingProduct();

                    zipcode_on_changevariant = jQueryNuvem("#product-shipping-container .js-shipping-input")
                        .val();
                    jQueryNuvem("#product-shipping-container .js-shipping-calculator-current-zip").text(
                        zipcode_on_changevariant);


                    LS.subscriptionChangeVariant(variant);
                }


                jQueryNuvem(document).on("change", ".js-variation-option", function(e) {
                    var $parent = jQueryNuvem(this).closest(".js-product-variants");
                    var $variants_group = jQueryNuvem(this).closest(".js-product-variants-group");
                    var $quickshop_parent_wrapper = jQueryNuvem(this).closest(
                        ".js-quickshop-container");


                    var quick_id = $quickshop_parent_wrapper.attr("data-quickshop-id");

                    if ($parent.hasClass("js-product-quickshop-variants")) {

                        var $quickshop_parent = jQueryNuvem(this).closest(".js-item-product");


                        if ($quickshop_parent.hasClass("js-item-slide")) {
                            var $quickshop_variant_selector =
                                '.js-swiper-slide-visible .js-quickshop-container[data-quickshop-id="' +
                                quick_id + '"]';
                        } else {
                            var $quickshop_variant_selector =
                                '.js-quickshop-container[data-quickshop-id="' + quick_id + '"]';
                        }

                        LS.changeVariant(changeVariant, $quickshop_variant_selector);


                        var selected_option_id = jQueryNuvem(this).val();
                        var $color_parent_to_update = jQueryNuvem(
                            '.js-quickshop-container[data-quickshop-id="' + quick_id + '"]');

                        $color_parent_to_update.find('.js-color-variant[data-option="' +
                                selected_option_id + '"]').addClass("selected").siblings()
                            .removeClass("selected");
                        $variants_group.find('.js-insta-variant[data-option="' +
                                selected_option_id + '"]').addClass("selected").siblings()
                            .removeClass("selected");

                    } else {
                        LS.changeVariant(changeVariant, '#single-product');
                    }


                    var $this_product_container = jQueryNuvem(this).closest(
                        ".js-product-container");

                    if ($this_product_container.hasClass("js-quickshop-container")) {
                        var this_quickshop_id = $this_product_container.attr("data-quickshop-id");
                        var $this_product_container = jQueryNuvem(
                            '.js-product-container[data-quickshop-id="' + this_quickshop_id +
                            '"]');
                    }
                    var $this_compare_price = $this_product_container.find(
                        ".js-compare-price-display");
                    var $this_price = $this_product_container.find(".js-price-display");
                    var $installment_container = $this_product_container.find(
                        ".js-product-payments-container");
                    var $installment_text = $this_product_container.find(
                        ".js-max-installments-container");
                    var $this_add_to_cart = $this_product_container.find(".js-prod-submit-form");

                    // Get the current product discount percentage value
                    var current_percentage_value = $this_product_container.find(
                        ".js-offer-percentage");

                    // Get the current product price and promotional price
                    var compare_price_value = $this_compare_price.html();
                    var price_value = $this_price.html();

                    // Calculate new discount percentage based on difference between filtered old and new prices
                    const percentageDifference = window.moneyDifferenceCalculator
                        .percentageDifferenceFromString(compare_price_value, price_value);
                    if (percentageDifference) {
                        $this_product_container.find(".js-offer-percentage").text(
                            percentageDifference);
                        $this_product_container.find(".js-offer-label").css("display", "table");
                    }

                    if ($this_compare_price.css("display") == "none" || !percentageDifference) {
                        $this_product_container.find(".js-offer-label").hide();
                    }
                    if ($this_add_to_cart.hasClass("nostock")) {
                        $this_product_container.find(".js-stock-label").show();
                        $this_product_container.find(".js-offer-label").hide();
                    } else {
                        $this_product_container.find(".js-stock-label").hide();
                    }
                    if ($this_price.css('display') == 'none') {
                        $installment_container.hide();
                        $installment_text.hide();
                    } else {
                        $installment_text.show();
                    }
                });



                jQueryNuvem(".js-product-form").on("submit", function(e) {
                    var button = jQueryNuvem(e.currentTarget).find('[type="submit"]');
                    button.attr('disabled', 'disabled');
                    if ((button.hasClass('contact')) || (button.hasClass('catalog'))) {
                        e.preventDefault();
                        var product_id = jQueryNuvem(e.currentTarget).find(
                            "input[name='add_to_cart']").val();
                        window.location = "\/contacto\/?product=" + product_id;
                    } else if (button.hasClass('cart')) {
                        button.val('Agregando...');
                    }
                });




                jQueryNuvem(document).on("click", ".js-quantity .js-quantity-up", function(e) {
                    $quantity_input = jQueryNuvem(this).closest(".js-quantity").find(
                        ".js-quantity-input");
                    $quantity_input.val(parseInt($quantity_input.val(), 10) + 1);
                });

                jQueryNuvem(document).on("click", ".js-quantity .js-quantity-down", function(e) {
                    $quantity_input = jQueryNuvem(this).closest(".js-quantity").find(
                        ".js-quantity-input");
                    quantity_input_val = $quantity_input.val();
                    if (quantity_input_val > 1) {
                        $quantity_input.val(parseInt($quantity_input.val(), 10) - 1);
                    }
                });





                var head_height = jQueryNuvem(".js-head-main").outerHeight();

                if (window.innerWidth > 768) {
                    jQueryNuvem("#cart-sticky-summary").css("top", (head_height + 10).toString() + 'px');
                }



                function getQuickShopImgSrc(element) {
                    const image = jQueryNuvem(element).closest('.js-quickshop-container').find('img');
                    return String(image.attr('srcset'));
                }

                jQueryNuvem(document).on("click", ".js-addtocart:not(.js-addtocart-placeholder)", function(
                    e) {


                    var $productContainer = jQueryNuvem(this).closest('.js-product-container');
                    var $productVariants = $productContainer.find(".js-variation-option");
                    var $productButton = $productContainer.find(
                        "input[type='submit'].js-addtocart");
                    var productButtonWidth = $productButton.first(el => el.offsetWidth);
                    var isQuickShop = $productContainer.hasClass('js-quickshop-container');
                    if (isQuickShop) {
                        var $productButtonContainer = $productButton.closest(
                            ".js-item-submit-container");
                    }
                    var isCrossSelling = $productContainer.hasClass('js-cross-selling-container');
                    var $productButtonPlaceholder = $productContainer.find(
                        ".js-addtocart-placeholder");
                    var $productButtonText = $productButtonPlaceholder.find(".js-addtocart-text");
                    var $productButtonAdding = $productButtonPlaceholder.find(
                        ".js-addtocart-adding");
                    var $productButtonSuccess = $productButtonPlaceholder.find(
                        ".js-addtocart-success");


                    if (isCrossSelling) {
                        var imageSrc = $productContainer.find('.js-cross-selling-product-image')
                            .attr('src');
                        var quantity = $productContainer.data('quantity')
                        var name = $productContainer.find('.js-cross-selling-product-name').text();
                        var price = $productContainer.find('.js-cross-selling-promo-price').text();
                        var addedToCartCopy = $productContainer.data('add-to-cart-translation');
                    } else if (!isQuickShop) {
                        if (jQueryNuvem(".js-product-slide-img.js-active-variant").length) {
                            var $activeVariantImg = $productContainer.find(
                                '.js-product-slide-img.js-active-variant');
                            var imageSrc = $activeVariantImg.attr('srcset') || $activeVariantImg
                                .data('srcset');
                        } else {
                            var $defaultImg = $productContainer.find('.js-product-slide-img');
                            var imageSrc = $defaultImg.attr('srcset') || $defaultImg.data('srcset');
                        }

                        imageSrc = imageSrc ? imageSrc.split(' ')[0] : '';
                        var quantity = $productContainer.find('.js-quantity-input').val();
                        var name = $productContainer.find('.js-product-name').text();
                        var price = $productContainer.find('.js-price-display').text();
                        var addedToCartCopy = "Agregar al carrito";
                    } else {
                        var imageSrc = getQuickShopImgSrc(this);
                        var quantity = 1;
                        var name = $productContainer.find('.js-item-name').text();
                        var price = $productContainer.find('.js-price-display').text().trim();
                        var addedToCartCopy = "Comprar";
                        if ($productContainer.hasClass("js-quickshop-has-variants")) {
                            var addedToCartCopy = "Agregar al carrito";
                        } else {
                            var addedToCartCopy = "Comprar";
                        }
                    }

                    if (!jQueryNuvem(this).hasClass('contact')) {

                        e.preventDefault();


                        $productButton.hide();
                        if (isQuickShop) {
                            $productButtonContainer.hide();
                        }

                        $productButtonPlaceholder.width(productButtonWidth).css('display', 'block');
                        $productButtonText.fadeOut();
                        $productButtonAdding.addClass("active");


                        function restore_button_initial_state() {
                            $productButtonAdding.removeClass("active");
                            $productButtonText.fadeIn();
                            $productButtonPlaceholder.removeAttr("style").hide();
                            $productButton.show();
                            if (isQuickShop) {
                                $productButtonContainer.show();
                            }
                        }


                        var subscription_callback_error = function() {
                            setTimeout(function() {
                                restore_button_initial_state();
                            }, 500);
                        };


                        const subscriptionValidResult = LS.subscriptionSubmit($productContainer,
                            subscription_callback_error, e);
                        if (subscriptionValidResult && subscriptionValidResult.changeCartSubmit) {
                            return;
                        }


                        var callback_add_to_cart = function(html_notification_related_products,
                            html_notification_cross_selling) {


                            jQueryNuvem('.js-cart-notification-item-img').attr('srcset',
                                imageSrc);
                            jQueryNuvem('.js-cart-notification-item-name').text(name);
                            jQueryNuvem('.js-cart-notification-item-quantity').text(quantity);
                            jQueryNuvem('.js-cart-notification-item-price').text(price);

                            if ($productVariants.length) {
                                var output = [];

                                $productVariants.each(function(el) {
                                    var variants = jQueryNuvem(el);
                                    output.push(variants.val());
                                });
                                jQueryNuvem(".js-cart-notification-item-variant-container")
                                    .show();
                                jQueryNuvem(".js-cart-notification-item-variant").text(output
                                    .join(', '))
                            } else {
                                jQueryNuvem(".js-cart-notification-item-variant-container")
                                    .hide();
                            }


                            var cartItemsBadge = jQueryNuvem(".js-cart-widget-amount");
                            var cartItemsMoney = jQueryNuvem(".js-cart-widget-total");
                            var cartItemsAmount = cartItemsBadge.text();

                            cartItemsBadge.removeClass("d-none d-md-inline-block");

                            if (window.innerWidth > 768) {
                                cartItemsMoney.removeClass("d-none d-md-inline-block");
                            }

                            if (cartItemsAmount > 1) {
                                jQueryNuvem(".js-cart-counts-plural").show();
                                jQueryNuvem(".js-cart-counts-singular").hide();
                            } else {
                                jQueryNuvem(".js-cart-counts-singular").show();
                                jQueryNuvem(".js-cart-counts-plural").hide();
                            }


                            $productButtonAdding.removeClass("active");
                            $productButtonSuccess.addClass("active");
                            setTimeout(function() {
                                $productButtonSuccess.removeClass("active");
                                $productButtonText.fadeIn();
                            }, 2000);
                            setTimeout(function() {
                                $productButtonPlaceholder.removeAttr("style").hide();
                                $productButton.show();
                                if (isQuickShop) {
                                    $productButtonContainer.show();
                                }
                            }, 3000);

                            $productContainer.find(".js-added-to-cart-product-message")
                                .slideDown();

                            if (isQuickShop) {
                                jQueryNuvem("#quickshop-modal").removeClass('modal-show');
                                jQueryNuvem(
                                        ".js-modal-overlay[data-modal-id='#quickshop-modal']")
                                    .hide();
                                jQueryNuvem("body").removeClass("overflow-none");
                                restoreQuickshopForm();
                                if (window.innerWidth < 768) {
                                    cleanURLHash();
                                }
                            }

                            let notificationWithRelatedProducts = false;



                            function recommendProductsOnAddToCart() {

                                jQueryNuvem('.js-related-products-notification-container').html(
                                    "");

                                modalOpen('#related-products-notification');

                                jQueryNuvem('.js-related-products-notification-container').html(
                                    html_notification_related_products).show();


                                // Set loop for recommended products

                                function calculateRelatedNotificationLoopVal(sectionSelector) {
                                    let productsAmount = jQueryNuvem(sectionSelector).attr(
                                        "data-related-amount");
                                    let loopVal = false;
                                    const applyLoop = (window.innerWidth < 768 &&
                                        productsAmount > 2.5) || (window.innerWidth > 768 &&
                                        productsAmount > 4);

                                    if (applyLoop) {
                                        loopVal = true;
                                    }

                                    return loopVal;
                                }

                                let cartRelatedLoopVal = calculateRelatedNotificationLoopVal(
                                    ".js-related-products-notification");

                                // Create new swiper on add to cart

                                createSwiper('.js-swiper-related-products-notification', {
                                    lazy: true,
                                    loop: cartRelatedLoopVal,
                                    watchOverflow: true,
                                    threshold: 5,
                                    watchSlideProgress: true,
                                    watchSlidesVisibility: true,
                                    spaceBetween: itemSwiperSpaceBetween,
                                    slideVisibleClass: 'js-swiper-slide-visible',
                                    slidesPerView: 2.5,
                                    navigation: {
                                        nextEl: '.js-swiper-related-products-notification-next',
                                        prevEl: '.js-swiper-related-products-notification-prev',
                                    },
                                    on: {
                                        afterInit: function() {
                                            hideSwiperControls(
                                                ".js-swiper-related-products-notification-prev",
                                                ".js-swiper-related-products-notification-next"
                                            );
                                        },
                                    },
                                    breakpoints: {
                                        768: {
                                            slidesPerView: 3,
                                        }
                                    }
                                });
                            }

                            notificationWithRelatedProducts =
                                html_notification_related_products != null;

                            if (notificationWithRelatedProducts) {
                                if (isQuickShop) {
                                    setTimeout(function() {
                                        recommendProductsOnAddToCart();
                                    }, 300);
                                } else {
                                    recommendProductsOnAddToCart();
                                }
                            }


                            let shouldShowCrossSellingModal = html_notification_cross_selling !=
                                null;

                            if (!notificationWithRelatedProducts) {

                                const cartOpenType = jQueryNuvem("#modal-cart").attr(
                                    'data-cart-open-type');

                                if ((cartOpenType === 'show_cart') && !
                                    shouldShowCrossSellingModal) {


                                    modalOpen('#modal-cart', 'openFullScreenWithoutClick');

                                } else {


                                    setTimeout(function() {
                                        jQueryNuvem(".js-alert-added-to-cart").show()
                                            .addClass("notification-visible")
                                            .removeClass("notification-hidden");

                                    }, 500);

                                    if (!cookieService.get(
                                            'first_product_added_successfully')) {
                                        cookieService.set('first_product_added_successfully', 1,
                                            7);
                                    } else {
                                        setTimeout(function() {
                                            jQueryNuvem(".js-alert-added-to-cart")
                                                .removeClass("notification-visible")
                                                .addClass("notification-hidden");
                                            setTimeout(function() {
                                                jQueryNuvem(
                                                    '.js-cart-notification-item-img'
                                                ).attr('src', '');
                                                jQueryNuvem(
                                                    ".js-alert-added-to-cart"
                                                ).hide();
                                            }, 2000);
                                        }, 8000);
                                    }
                                }
                            }


                            if (html_notification_cross_selling != null) {
                                jQueryNuvem('.js-cross-selling-modal-body').html("");
                                modalOpen('#js-cross-selling-modal');
                                jQueryNuvem('.js-cross-selling-modal-body').html(
                                    html_notification_cross_selling).show();
                            }


                            const crossSellingContainer = document.querySelector(
                                '.js-cross-selling-container');

                            if (crossSellingContainer) {
                                LS.fillCrossSelling(crossSellingContainer);
                            }



                            if (jQueryNuvem("#product-shipping-container .js-shipping-input")
                                .val()) {
                                zipcode_on_addtocart = jQueryNuvem(
                                    "#product-shipping-container .js-shipping-input").val();
                                jQueryNuvem("#cart-shipping-container .js-shipping-input").val(
                                    zipcode_on_addtocart);
                                jQueryNuvem(".js-shipping-calculator-current-zip").text(
                                    zipcode_on_addtocart);
                            } else if (cookieService.get('calculator_zipcode')) {
                                var zipcode_from_cookie = cookieService.get(
                                    'calculator_zipcode');
                                jQueryNuvem('.js-shipping-input').val(zipcode_from_cookie);
                                jQueryNuvem(".js-shipping-calculator-current-zip").text(
                                    zipcode_from_cookie);
                            }


                            jQueryNuvem(".js-fs-add-this-product").hide();
                            jQueryNuvem(".js-fs-add-one-more").show();



                            if (isCrossSelling) {
                                jQueryNuvem('#js-cross-selling-modal .js-modal-close').trigger(
                                    'click');
                            }
                        }
                        var callback_error = function() {
                            restore_button_initial_state();
                        }
                        $prod_form = jQueryNuvem(this).closest("form");
                        LS.addToCartEnhanced(
                            $prod_form,
                            addedToCartCopy,
                            'Agregando...',
                            'No hay más stock de este producto.',
                            false,
                            callback_add_to_cart,
                            callback_error
                        );
                    }
                });



                jQueryNuvem(document).on("keypress", ".js-cart-quantity-input", function(e) {
                    if (e.which != 8 && e.which != 0 && (e.which < 48 || e.which > 57)) {
                        return false;
                    }
                });

                jQueryNuvem(document).on("focusout", ".js-cart-quantity-input", function(e) {
                    var itemID = jQueryNuvem(this).attr("data-item-id");
                    var itemVAL = jQueryNuvem(this).val();
                    if (itemVAL == 0) {
                        var r = confirm("¿Seguro que quieres borrar este artículo?");
                        if (r == true) {
                            LS.removeItem(itemID, true);
                        } else {
                            jQueryNuvem(this).val(1);
                        }
                    } else {
                        LS.changeQuantity(itemID, itemVAL, true);
                    }
                });


                jQueryNuvem(".js-trigger-empty-cart-alert").on("click", function(e) {
                    e.preventDefault();
                    let emptyCartAlert = jQueryNuvem(".js-mobile-nav-empty-cart-alert").fadeIn(100);
                    setTimeout(() => emptyCartAlert.fadeOut(500), 1500);
                });


                document.addEventListener('cart.released', () => {
                    const cart_amount = jQueryNuvem(".js-cart-widget-amount").text();
                    if (cart_amount == 1) {
                        jQueryNuvem(".js-amount-one-item").show();
                        jQueryNuvem(".js-amount-many-items").hide();
                    } else {
                        jQueryNuvem(".js-amount-one-item").hide();
                        jQueryNuvem(".js-amount-many-items").show();
                    }
                });



                jQueryNuvem('form[action="\/comprar\/"]').on("submit", function() {
                    cookieService.remove('first_product_added_successfully');
                });




                if (jQueryNuvem('.js-selected-shipping-method').length) {
                    var shipping_cost = jQueryNuvem('.js-selected-shipping-method').data("cost");
                    var $shippingCost = jQueryNuvem("#shipping-cost");
                    $shippingCost.text(shipping_cost);
                    $shippingCost.removeClass('opacity-40');
                }


                selectShippingOption = function(elem, save_option) {
                    jQueryNuvem(".js-shipping-method, .js-branch-method").removeClass(
                        'js-selected-shipping-method');
                    jQueryNuvem(elem).addClass('js-selected-shipping-method');


                    var shipping_cost = jQueryNuvem(elem).data("cost");
                    var shipping_price_clean = jQueryNuvem(elem).data("price");

                    if (shipping_price_clean = 0.00) {
                        var shipping_cost = ''
                    }

                    // Updates shipping (ship and pickup) cost on cart
                    var $shippingCost = jQueryNuvem("#shipping-cost");
                    $shippingCost.text(shipping_cost);
                    $shippingCost.removeClass('opacity-40');


                    if (save_option) {
                        LS.saveCalculatedShipping(true);
                    }
                    if (jQueryNuvem(elem).hasClass("js-shipping-method-hidden")) {
                        if (jQueryNuvem(elem).hasClass("js-pickup-option")) {
                            jQueryNuvem(
                                ".js-other-pickup-options, .js-show-other-pickup-options .js-shipping-see-less"
                            ).show();
                            jQueryNuvem(".js-show-other-pickup-options .js-shipping-see-more").hide();
                        } else {
                            jQueryNuvem(
                                ".js-other-shipping-options, .js-show-more-shipping-options .js-shipping-see-less"
                            ).show();
                            jQueryNuvem(".js-show-more-shipping-options .js-shipping-see-more").hide()
                        }
                    }
                };


                if (cookieService.get('calculator_zipcode')) {


                    var zipcode_from_cookie = cookieService.get('calculator_zipcode');



                    jQueryNuvem('#product-shipping-container .js-shipping-input').val(zipcode_from_cookie);


                    jQueryNuvem(".js-shipping-calculator-current-zip").text(zipcode_from_cookie);


                    jQueryNuvem(".js-shipping-calculator-head").addClass("with-zip").removeClass(
                        "with-form");
                    jQueryNuvem(".js-shipping-calculator-with-zipcode").addClass("transition-up-active");
                    jQueryNuvem(".js-shipping-calculator-spinner").show();
                } else {


                    jQueryNuvem(".js-shipping-calculator-form").addClass("transition-up-active");
                }


                removeShippingSuboptions = function() {
                    var shipping_suboptions_id = jQueryNuvem(".js-modal-shipping-suboptions").attr(
                        "id");
                    jQueryNuvem("#" + shipping_suboptions_id).remove();
                    jQueryNuvem('.js-modal-overlay[data-modal-id="#' + shipping_suboptions_id + '"')
                        .remove();
                };



                jQueryNuvem(".js-calculate-shipping").on("click", function(e) {
                    e.preventDefault();

                    let shipping_input_val = jQueryNuvem(e.currentTarget).closest(
                        ".js-shipping-calculator-form").find(".js-shipping-input").val();

                    jQueryNuvem(".js-shipping-input").val(shipping_input_val);


                    if (jQueryNuvem(".js-cart-item").length) {
                        LS.calculateShippingAjax(
                            jQueryNuvem('#cart-shipping-container').find(".js-shipping-input")
                            .val(),
                            '\/envio\/',
                            jQueryNuvem("#cart-shipping-container").closest(
                                ".js-shipping-calculator-container"));
                    }

                    jQueryNuvem(".js-shipping-calculator-current-zip").html(shipping_input_val);
                    removeShippingSuboptions();
                });


                jQueryNuvem(".js-shipping-input").on('keydown', function(e) {
                    var key = e.which ? e.which : e.keyCode;
                    var enterKey = 13;
                    if (key === enterKey) {
                        e.preventDefault();
                        jQueryNuvem(e.currentTarget).closest(".js-shipping-calculator-form").find(
                            ".js-calculate-shipping").trigger('click');
                        if (window.innerWidth < 768) {
                            jQueryNuvem(e.currentTarget).trigger('blur');
                        }
                    }
                });


                jQueryNuvem(document).on("change", ".js-shipping-method, .js-branch-method", function(e) {
                    selectShippingOption(this, true);
                    jQueryNuvem(".js-shipping-method-unavailable").hide();
                });


                jQueryNuvem(document).on('shipping.options.checked', '.js-shipping-method', function(e) {
                    let shippingPrice = jQueryNuvem(this).attr("data-price");
                    LS.addToTotal(shippingPrice);

                    let total = (LS.data.cart.total / 100) + parseFloat(shippingPrice);
                    jQueryNuvem(".js-cart-widget-total").html(LS.formatToCurrency(total));

                    selectShippingOption(this, false);
                });


                jQueryNuvem(document).on("click", ".js-toggle-more-shipping-options", function(e) {
                    e.preventDefault();


                    if (jQueryNuvem(this).hasClass("js-show-other-pickup-options")) {
                        jQueryNuvem(".js-other-pickup-options").slideToggle(600);
                        jQueryNuvem(
                            ".js-show-other-pickup-options .js-shipping-see-less, .js-show-other-pickup-options .js-shipping-see-more"
                        ).toggle();
                    } else {
                        jQueryNuvem(".js-other-shipping-options").slideToggle(600);
                        jQueryNuvem(
                            ".js-show-more-shipping-options .js-shipping-see-less, .js-show-more-shipping-options .js-shipping-see-more"
                        ).toggle();
                    }
                });



                calculateCartShippingOnLoad = function() {
                    if (jQueryNuvem("#cart-shipping-container .js-shipping-input").val()) {
                        // If user already had calculated shipping: recalculate shipping
                        setTimeout(function() {
                            LS.calculateShippingAjax(
                                jQueryNuvem('#cart-shipping-container').find(
                                    ".js-shipping-input").val(),
                                '\/envio\/',
                                jQueryNuvem("#cart-shipping-container").closest(
                                    ".js-shipping-calculator-container"));
                            removeShippingSuboptions();
                            window.toggleAccordionPrivate(
                                "#cart-shipping-container .js-toggle-shipping");
                        }, 100);
                    }

                    if (jQueryNuvem(".js-branch-method").hasClass('js-selected-shipping-method')) {}
                };



                jQueryNuvem(document).on("click", ".js-shipping-calculator-change-zipcode", function(e) {
                    e.preventDefault();
                    jQueryNuvem(".js-shipping-calculator-response").fadeOut(100);
                    jQueryNuvem(".js-shipping-calculator-head").addClass("with-form").removeClass(
                        "with-zip");
                    jQueryNuvem(".js-shipping-calculator-with-zipcode").removeClass(
                        "transition-up-active");
                    jQueryNuvem(".js-shipping-calculator-form").addClass("transition-up-active");
                });





                jQueryNuvem(document).on("click", ".js-save-shipping-country", function(e) {

                    e.preventDefault();


                    lang_select_option = jQueryNuvem(this).closest(".js-modal-shipping-country");
                    changeLang(lang_select_option);

                    jQueryNuvem(this).text('Aplicando...').addClass("disabled");
                });



                var isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream;
                if (isIOS) {
                    var ios_input_fields = jQueryNuvem(
                        "input[type='text'], input[type='number'], input[type='password'], input[type='tel'], textarea, input[type='search'], input[type='hidden'], input[type='email']"
                    );
                    ios_input_fields.addClass("form-control-ios");
                    jQueryNuvem(".js-quantity").addClass("form-group-quantity-ios");
                    jQueryNuvem(".js-cart-quantity-container").addClass("cart-quantity-container-ios");
                    jQueryNuvem(".js-search-form").toggleClass("search-form-ios");
                    jQueryNuvem(".js-price-filter-btn").addClass("price-btn-ios");
                    jQueryNuvem(".js-price-filter-empty").addClass("input-clear-content-ios");
                }







                var width = window.innerWidth;
                if (width > 767) {
                    var slider_empty_autoplay = {
                        delay: 6000,
                    };
                } else {
                    var slider_empty_autoplay = false;
                }

                window.homeEmptySlider = {
                    getAutoRotation: function() {
                        return slider_empty_autoplay;
                    },
                };
                createSwiper('.js-home-empty-slider', {
                    lazy: true,
                    loop: true,
                    autoplay: slider_empty_autoplay,
                    pagination: {
                        el: '.js-swiper-empty-home-pagination',
                        clickable: true,
                    },
                    navigation: {
                        nextEl: '.js-swiper-empty-home-next',
                        prevEl: '.js-swiper-empty-home-prev',
                    },
                    on: {
                        init: function() {
                            jQueryNuvem(".js-home-empty-slider").css("visibility", "visible")
                                .css("height", "100%");
                        },
                    },
                });





                createSwiper('.js-swiper-product-demo', {
                    lazy: true,
                    slidesPerView: 'auto',
                    watchOverflow: true,
                    navigation: {
                        nextEl: '.js-swiper-product-next-demo',
                        prevEl: '.js-swiper-product-prev-demo',
                    },
                    pagination: {
                        el: '.js-swiper-product-pagination-demo',
                    },
                    breakpoints: {
                        768: {
                            slidesPerView: 'auto',
                        }
                    },
                });

                var directionVal = 'vertical';


                createSwiper('.js-swiper-product-thumbs-demo', {
                    lazy: true,
                    watchOverflow: true,
                    threshold: 5,
                    direction: directionVal,
                    navigation: {
                        nextEl: '.js-swiper-product-thumbs-next-demo',
                        prevEl: '.js-swiper-product-thumbs-prev-demo',
                    },
                    slidesPerView: 'auto',
                });



            });

            // Recife Search Form - Redirect to categories with search parameter
            const recifeSearchForm = document.getElementById('recifeSearchForm');
            const recifeSearchInput = document.getElementById('recifeSearchInput');

            if (recifeSearchForm && recifeSearchInput) {
                recifeSearchForm.addEventListener('submit', function(e) {
                    e.preventDefault();
                    const query = recifeSearchInput.value.trim();
                    if (query) {
                        window.location.href = "{{ route('tienda.categorias', $empresa->slug) }}?buscar=" +
                            encodeURIComponent(query);
                    }
                });

                recifeSearchInput.addEventListener('keypress', function(e) {
                    if (e.key === 'Enter') {
                        e.preventDefault();
                        recifeSearchForm.dispatchEvent(new Event('submit'));
                    }
                });
            }

            // Search Modal - Based on sport_layout.blade.php
            const searchModal = document.getElementById('nav-search');
            const searchOverlay = document.querySelector('.js-modal-overlay[data-modal-id="#nav-search"]');
            const openSearchBtn = document.querySelector(
                '.js-search-button, .js-modal-open[data-toggle="#nav-search"], a[aria-label="Buscador"]');
            const closeSearchBtns = document.querySelectorAll(
                '#nav-search .js-modal-close, #nav-search .js-fullscreen-modal-close');

            function openSearch() {
                if (searchModal && searchOverlay) {
                    searchModal.style.display = 'block';
                    searchOverlay.style.display = 'block';
                    document.body.style.overflow = 'hidden';
                    setTimeout(() => {
                        if (recifeSearchInput) {
                            recifeSearchInput.focus();
                        }
                    }, 300);
                }
            }

            function closeSearch() {
                if (searchModal && searchOverlay) {
                    searchModal.style.display = 'none';
                    searchOverlay.style.display = 'none';
                    document.body.style.overflow = '';
                }
            }

            if (openSearchBtn) {
                openSearchBtn.addEventListener('click', function(e) {
                    e.preventDefault();
                    openSearch();
                });
            }

            if (closeSearchBtns) {
                closeSearchBtns.forEach(function(btn) {
                    btn.addEventListener('click', function(e) {
                        e.preventDefault();
                        closeSearch();
                    });
                });
            }

            if (searchOverlay) {
                searchOverlay.addEventListener('click', function() {
                    if (searchModal.style.display === 'block') {
                        closeSearch();
                    }
                });
            }

            document.addEventListener('keydown', function(e) {
                if (e.key === 'Escape' && searchModal && searchModal.style.display === 'block') {
                    closeSearch();
                }
            });

            // Hamburger Menu Modal - Vanilla JS fallback for mobile categories
            const hamburgerModal = document.getElementById('nav-hamburger');
            const hamburgerOverlay = document.querySelector('.js-modal-overlay[data-modal-id="#nav-hamburger"]');
            const openHamburgerBtn = document.querySelector('.js-modal-open[data-toggle="#nav-hamburger"]');
            const closeHamburgerBtns = document.querySelectorAll('#nav-hamburger .js-modal-close, #nav-hamburger .js-toggle-menu-close');

            function openHamburger() {
                if (hamburgerModal && hamburgerOverlay) {
                    hamburgerModal.style.display = 'block';
                    hamburgerOverlay.style.display = 'block';
                    document.body.style.overflow = 'hidden';
                    setTimeout(() => {
                        hamburgerModal.classList.add('modal-show');
                    }, 10);
                }
            }

            function closeHamburger() {
                if (hamburgerModal && hamburgerOverlay) {
                    hamburgerModal.classList.remove('modal-show');
                    setTimeout(() => {
                        hamburgerModal.style.display = 'none';
                        hamburgerOverlay.style.display = 'none';
                        document.body.style.overflow = '';
                    }, 300);
                }
            }

            if (openHamburgerBtn) {
                openHamburgerBtn.addEventListener('click', function(e) {
                    e.preventDefault();
                    openHamburger();
                });
            }

            if (closeHamburgerBtns) {
                closeHamburgerBtns.forEach(function(btn) {
                    btn.addEventListener('click', function(e) {
                        e.preventDefault();
                        closeHamburger();
                    });
                });
            }

            if (hamburgerOverlay) {
                hamburgerOverlay.addEventListener('click', function() {
                    closeHamburger();
                });
            }

            // Close hamburger on Escape key
            document.addEventListener('keydown', function(e) {
                if (e.key === 'Escape' && hamburgerModal && hamburgerModal.style.display === 'block') {
                    closeHamburger();
                }
            });

            // Hamburger submenu panel toggle (for categories)
            const toggleMenuPanels = document.querySelectorAll('#nav-hamburger .js-toggle-menu-panel');
            const toggleMenuBacks = document.querySelectorAll('#nav-hamburger .js-toggle-menu-back');

            toggleMenuPanels.forEach(function(panel) {
                panel.addEventListener('click', function(e) {
                    e.preventDefault();
                    const subPanel = this.nextElementSibling;
                    if (subPanel && subPanel.classList.contains('js-menu-panel')) {
                        subPanel.style.display = 'block';
                        setTimeout(() => {
                            subPanel.classList.add('nav-list-panel-show');
                        }, 10);
                    }
                });
            });

            toggleMenuBacks.forEach(function(backBtn) {
                backBtn.addEventListener('click', function(e) {
                    e.preventDefault();
                    const subPanel = this.closest('.js-menu-panel');
                    if (subPanel) {
                        subPanel.classList.remove('nav-list-panel-show');
                        setTimeout(() => {
                            subPanel.style.display = 'none';
                        }, 300);
                    }
                });
            });

        });
    </script>





