                flex-direction: row;
            }
            #searchModal .search-input {
                flex: 1;
            }
            #searchModal .search-buttons {
                flex-shrink: 0;
            }
            #searchModal .search-buttons .btn {
                padding: 12px 30px;
            }
        }
    </style>
    <div id="searchOverlay"></div>
    <div id="searchModal">
        <div class="search-container">
            <div class="search-input-wrapper">
                <input type="text" class="search-input" placeholder="Buscar productos..." id="searchInput">
                <div class="search-buttons">
                    <button class="btn" id="searchSubmitBtn">BUSCAR</button>
                    <button class="btn" id="closeSearchBtn">CERRAR</button>
                </div>
            </div>
        </div>
    </div>

    <script>
        // Search Modal functionality - Wait for DOM to be ready
        (function() {
            function initSearchModal() {
                const searchModal = document.getElementById('searchModal');
                const searchOverlay = document.getElementById('searchOverlay');
                const openSearchBtn = document.querySelector('.js-search-button');
                const closeSearchBtn = document.getElementById('closeSearchBtn');
                const searchInput = document.getElementById('searchInput');
                const searchSubmitBtn = document.getElementById('searchSubmitBtn');

                if (!openSearchBtn) {
                    console.warn('Search button (.js-search-button) not found');
                    return;
                }

                if (!searchModal || !searchOverlay) {
                    console.warn('Search modal elements not found');
                    return;
                }

                function openSearch() {
                    searchModal.style.top = '0';
                    searchOverlay.style.display = 'block';
                    setTimeout(() => {
                        searchOverlay.style.opacity = '1';
                    }, 10);
                    document.body.style.overflow = 'hidden';
                    setTimeout(() => {
                        if (searchInput) searchInput.focus();
                    }, 300);
                }

                function closeSearch() {
                    searchModal.style.top = '-100%';
                    searchOverlay.style.opacity = '0';
                    setTimeout(() => {
                        searchOverlay.style.display = 'none';
                    }, 300);
                    document.body.style.overflow = '';
                }

                openSearchBtn.addEventListener('click', function(e) {
                    e.preventDefault();
                    e.stopPropagation();
                    openSearch();
                });

                if (closeSearchBtn) {
                    closeSearchBtn.addEventListener('click', closeSearch);
                }
                searchOverlay.addEventListener('click', closeSearch);

                if (searchSubmitBtn && searchInput) {
                    searchSubmitBtn.addEventListener('click', function() {
                        const query = searchInput.value.trim();
                        if (query) {
                            window.location.href = "{{ route('tienda.categorias', $empresa->slug) }}?buscar=" +
                                encodeURIComponent(query);
                        }
                    });

                    searchInput.addEventListener('keypress', function(e) {
                        if (e.key === 'Enter') {
                            searchSubmitBtn.click();
                        }
                    });
                }

                // Close modal on Escape key
                document.addEventListener('keydown', function(e) {
                    if (e.key === 'Escape' && searchModal.style.top === '0px') {
                        closeSearch();
                    }
                });

                console.log('Search modal initialized successfully');
            }

            // Wait for DOM to be ready
            if (document.readyState === 'loading') {
                document.addEventListener('DOMContentLoaded', initSearchModal);
            } else {
                initSearchModal();
            }
        })();

        var directionVal = 'vertical';


        createSwiper('.js-swiper-product-thumbs-demo', {
        lazy: true,
        watchOverflow: true,
        threshold: 5,
        direction: directionVal,
        navigation: {
            nextEl: '.js-swiper-product-thumbs-next-demo',
            prevEl: '.js-swiper-product-thumbs-prev-demo',
        },
        slidesPerView: 'auto',
        });

        // Recife Search Form - Redirect to categories with search parameter
        const recifeSearchForm = document.getElementById('recifeSearchForm');
        const recifeSearchInput = document.getElementById('recifeSearchInput');

        if (recifeSearchForm && recifeSearchInput) {
            recifeSearchForm.addEventListener('submit', function(e) {
                e.preventDefault();
                const query = recifeSearchInput.value.trim();
                if (query) {
                    window.location.href = "{{ route('tienda.categorias', $empresa->slug) }}?buscar=" +
                        encodeURIComponent(query);
                }
            });

            recifeSearchInput.addEventListener('keypress', function(e) {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    recifeSearchForm.dispatchEvent(new Event('submit'));
                }
            });
        }

        // Duplicate search modal code removed - using #searchModal instead
    </script>





